#pragma once
#include <cstddef>
#include <span>
#include <vector>
#include <atomic>
#include <optional>
#include <string>
#include <string_view>
#include <iterator>
#include <cassert>
namespace ws {
class Buffer {
public:
    Buffer(std::size_t size = 1000) noexcept;
    Buffer(std::span<const std::byte> bytes) noexcept;
    Buffer(std::initializer_list<std::byte> bytes) noexcept;
    Buffer(std::string_view str) noexcept;
    Buffer(const Buffer&) noexcept;
    Buffer(Buffer&&) noexcept;
    Buffer& operator=(const Buffer&) noexcept;
    Buffer& operator=(Buffer&&) noexcept;
    std::size_t WritableSize() const noexcept;
    std::size_t ReadableSize() const noexcept;
    std::optional<std::byte> Peek() const noexcept;
    std::span<const std::byte> ReadableBytes() const noexcept;
    std::string ReadableString() const noexcept;
    std::span<std::byte> WritableBytes() const noexcept;
    void Append(std::span<const std::byte> bytes) noexcept;
    void Append(std::initializer_list<std::byte> bytes) noexcept;
    void Append(std::string_view str, std::optional<NewLine> new_line = std::nullopt) noexcept;
    void Append(const void* data, std::size_t size) noexcept;
    void Append(const Buffer& buf) noexcept;
    void EnsureWriteableSize(std::size_t size) noexcept;
    void HasWritten(std::size_t size) noexcept;
    void Retrieve(std::size_t size) noexcept;
    std::size_t RetrieveUntil(const void* addr) noexcept;
    std::size_t RetrieveAll() noexcept;
    std::string RetrieveAllToString() noexcept;
    void Clear() noexcept;
    bool Empty() const noexcept;
protected:
    std::size_t PrependableSize() const noexcept;
    void MakeSpace(std::size_t size) noexcept;
    std::vector<std::byte>::iterator ReadIter() const noexcept;
    std::vector<std::byte>::iterator WriteIter() const noexcept;
private:
    std::vector<std::byte> buf_;
    std::atomic<std::size_t> read_pos_ {0};
    std::atomic<std::size_t> write_pos_ {0};
};
class IOBuffer : public Buffer {
public:
    IOBuffer() noexcept = default;
    std::size_t ReadFrom(io::IReadWriter& io);
    std::size_t WriteTo(io::IReadWriter& io);
};
}

namespace ws {
Buffer::Buffer(std::size_t size) noexcept : buf_(size), read_pos_(0), write_pos_(0) {}

Buffer::Buffer(std::span<const std::byte> bytes) noexcept : buf_(bytes.begin(), bytes.end()), read_pos_(0), write_pos_(bytes.size()) {}

Buffer::Buffer(std::initializer_list<std::byte> bytes) noexcept : buf_(bytes), read_pos_(0), write_pos_(bytes.size()) {}

Buffer::Buffer(std::string_view str) noexcept : buf_(str.begin(), str.end()), read_pos_(0), write_pos_(str.size()) {}

Buffer::Buffer(const Buffer& o) noexcept : buf_(o.buf_), read_pos_(o.read_pos_.load()), write_pos_(o.write_pos_.load()) {}

Buffer::Buffer(Buffer&& o) noexcept : buf_(std::move(o.buf_)), read_pos_(o.read_pos_.load()), write_pos_(o.write_pos_.load()) {
    o.read_pos_ = 0;
    o.write_pos_ = 0;
}

Buffer& Buffer::operator=(const Buffer& o) noexcept {
    if (this != &o) {
        buf_ = o.buf_;
        read_pos_ = o.read_pos_.load();
        write_pos_ = o.write_pos_.load();
    }
    return *this;
}

Buffer& Buffer::operator=(Buffer&& o) noexcept {
    if (this != &o) {
        buf_ = std::move(o.buf_);
        read_pos_ = o.read_pos_.load();
        write_pos_ = o.write_pos_.load();
        o.read_pos_ = 0;
        o.write_pos_ = 0;
    }
    return *this;
}

std::size_t Buffer::WritableSize() const noexcept {
    return buf_.size() - write_pos_;
}

std::size_t Buffer::ReadableSize() const noexcept {
    return write_pos_ - read_pos_;
}

std::optional<std::byte> Buffer::Peek() const noexcept {
    if (read_pos_ < write_pos_) {
        return buf_[read_pos_];
    }
    return std::nullopt;
}

std::span<const std::byte> Buffer::ReadableBytes() const noexcept {
    return {buf_.data() + read_pos_, ReadableSize()};
}

std::string Buffer::ReadableString() const noexcept {
    return std::string(reinterpret_cast<const char*>(buf_.data() + read_pos_), ReadableSize());
}

std::span<std::byte> Buffer::WritableBytes() const noexcept {
    return {buf_.data() + write_pos_, WritableSize()};
}

void Buffer::Append(std::span<const std::byte> bytes) noexcept {
    EnsureWriteableSize(bytes.size());
    std::copy(bytes.begin(), bytes.end(), WriteIter().base());
    HasWritten(bytes.size());
}

void Buffer::Append(std::initializer_list<std::byte> bytes) noexcept {
    Append({bytes.begin(), bytes.end()});
}

void Buffer::Append(std::string_view str, std::optional<NewLine> new_line) noexcept {
    std::string full_str(str);
    if (new_line.has_value()) {
        switch (*new_line) {
            case NewLine::LF:
                full_str += "\n";
                break;
            case NewLine::CRLF:
                full_str += "\r\n";
                break;
        }
    }
    Append({reinterpret_cast<const std::byte*>(full_str.data()), full_str.length()});
}

void Buffer::Append(const void* data, std::size_t size) noexcept {
    Append({static_cast<const std::byte*>(data), size});
}

void Buffer::Append(const Buffer& buf) noexcept {
    Append(buf.ReadableBytes());
}

void Buffer::EnsureWriteableSize(std::size_t size) noexcept {
    if (WritableSize() < size) {
        MakeSpace(size);
    }
}

void Buffer::HasWritten(std::size_t size) noexcept {
    write_pos_ += size;
}

void Buffer::Retrieve(std::size_t size) noexcept {
    read_pos_ += size;
}

std::size_t Buffer::RetrieveUntil(const void* addr) noexcept {
    const std::byte* end = static_cast<const std::byte*>(addr);
    auto begin = ReadIter().base();
    assert(begin <= end);
    std::size_t read_size = end - begin;
    Retrieve(read_size);
    return read_size;
}

std::size_t Buffer::RetrieveAll() noexcept {
    std::size_t size = ReadableSize();
    Retrieve(size);
    return size;
}

std::string Buffer::RetrieveAllToString() noexcept {
    std::string result(ReadableString());
    RetrieveAll();
    return result;
}

void Buffer::Clear() noexcept {
    read_pos_ = 0;
    write_pos_ = 0;
}

bool Buffer::Empty() const noexcept {
    return ReadableSize() == 0;
}

std::size_t Buffer::PrependableSize() const noexcept {
    return read_pos_;
}

void Buffer::MakeSpace(std::size_t size) noexcept {
    if (WritableSize() + PrependableSize() < size) {
        buf_.resize(write_pos_ + size);
    } else {
        std::copy(ReadIter().base(), WriteIter().base(), buf_.data());
        write_pos_ -= read_pos_;
        read_pos_ = 0;
    }
}

std::vector<std::byte>::iterator Buffer::ReadIter() const noexcept {
    return buf_.begin() + read_pos_;
}

std::vector<std::byte>::iterator Buffer::WriteIter() const noexcept {
    return buf_.begin() + write_pos_;
}
}
